// =============================================================================
// AdmitPath — Comprehensive College Details Database
// Top 25 schools with real admissions data for the 2026 cycle
// =============================================================================

export interface CollegeDetail {
  slug: string;
  name: string;
  location: {
    city: string;
    state: string;
    region: string;
    setting: "urban" | "suburban" | "rural" | "small-city";
  };

  admissions: {
    acceptanceRate: number;
    edAcceptanceRate?: number;
    ed2AcceptanceRate?: number;
    eaAcceptanceRate?: number;
    reaAcceptanceRate?: number;
    rdAcceptanceRate?: number;
    totalApplicants: number;
    totalAdmitted: number;
    enrolled: number;
    yieldRate: number;
    applicationDeadlines: {
      ed?: string;
      ed1?: string;
      ed2?: string;
      ea?: string;
      rea?: string;
      rd: string;
    };
    testPolicy: "required" | "test-optional" | "test-blind";
    satRange: { p25: number; p75: number };
    actRange: { p25: number; p75: number };
    gpaAvg: number;
    demonstratedInterest:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    legacyPolicy: "considered" | "not-considered";
    interviewPolicy:
      | "required"
      | "recommended"
      | "optional"
      | "not-offered";
  };

  financial: {
    tuitionInState?: number;
    tuitionOutOfState: number;
    roomAndBoard: number;
    totalCOA: number;
    needBlind: boolean;
    needBlindInternational: boolean;
    meetsFullNeed: boolean;
    noLoanPolicy: boolean;
    avgFinancialAid: number;
    pctReceivingAid: number;
    avgDebt: number;
    endowment: string;
    netPriceByIncome: {
      under30k: number;
      from30to48k: number;
      from48to75k: number;
      from75to110k: number;
      over110k: number;
    };
  };

  academics: {
    type: "private" | "public" | "public-ivy";
    classification:
      | "research-1"
      | "research-2"
      | "liberal-arts"
      | "specialized";
    totalEnrollment: number;
    undergradEnrollment: number;
    studentFacultyRatio: string;
    avgClassSize: number;
    pctClassesUnder20: number;
    topMajors: string[];
    specialPrograms: string[];
    gradRate4yr: number;
    gradRate6yr: number;
    retentionRate: number;
    phiBetaKappa: boolean;
    studyAbroad: { pctParticipating: number; programs: number };
  };

  campusLife: {
    housing: { guaranteed: string; pctOnCampus: number };
    greekLife: { pctMen: number; pctWomen: number };
    athletics: { division: string; conference: string; notable: string[] };
    clubsAndOrgs: number;
    socialScene: string;
    diversity: {
      white: number;
      asian: number;
      hispanic: number;
      black: number;
      international: number;
      firstGen: number;
    };
  };

  outcomes: {
    medianEarnings10yr: number;
    topEmployers: string[];
    topGradSchools: string[];
    pctEmployed6mo: number;
    pctGradSchool: number;
    notableAlumni: string[];
  };

  strategy: {
    whatTheyLookFor: string[];
    supplementEssays: { prompt: string; wordLimit: number; tip: string }[];
    commonMistakes: string[];
    insiderTips: string[];
    bestFitFor: string[];
    worstFitFor: string[];
  };

  cdsWeights: {
    rigor:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    gpa: "very-important" | "important" | "considered" | "not-considered";
    classRank:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    testScores:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    essay:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    recommendations:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    extracurriculars:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    talent:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    character:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    firstGen:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    alumni:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    geographic:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    stateResidency:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    volunteerWork:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    workExperience:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
    interest:
      | "very-important"
      | "important"
      | "considered"
      | "not-considered";
  };
}

