// =============================================================================
// LOOKUP FUNCTION
// =============================================================================

/**
 * Find a college detail by its slug.
 * Returns undefined if no matching college is found.
 */
export function findCollegeDetail(
  slug: string
): CollegeDetail | undefined {
  return COLLEGE_DETAILS.find(
    (college) => college.slug === slug.toLowerCase()
  );
}

/**
 * Find colleges by partial name match (case-insensitive).
 */
export function searchCollegeDetails(query: string): CollegeDetail[] {
  const lowerQuery = query.toLowerCase();
  return COLLEGE_DETAILS.filter(
    (college) =>
      college.name.toLowerCase().includes(lowerQuery) ||
      college.slug.includes(lowerQuery)
  );
}

/**
 * Get all college slugs for iteration.
 */
export function getAllCollegeSlugs(): string[] {
  return COLLEGE_DETAILS.map((college) => college.slug);
}
